INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (765,'VIBRANCE','VIBRANCE is unique because of our personalised approach. We connect you with a community of like-minded successful people and provide a range of member benefits through our strategic alliances. We take special care to personally interview quality candidates and we personally match and organise your dates.','/images/vibrance_120x79.jpg','http://www.vibrance.net.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (766,'Mango Dance','Sydney''s First Bollywood Dance School as seen on Australian Idol. Mango works hard to provide students from Beginner to Professional level dance tuition in: Bollywood, Jazz, Funk, Hip Hop, Lyrical Jazz, Broadway Jazz, Locking, Popping, Classical Ballet, Contemporary, Bellydance and Latin Dance Styles. New dance force in Sydney!','/images/Mango-Dance-Studio_100x94.gif','http://www.mangodance.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (767,'Singles Social Dance','Horns Plus Big Band brings you a classic big band line-up showcasing all styles of jazz, wth a dynamic line up of five trumpets, four trombones, five saxes, rhythm section and female vocalist 7.30pm - 12.30am 2nd and 4th Friday of every month.','/images/jazzband_160x101.jpg','',NULL,NULL,NULL);
