INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (769,'Adelaide Speed Date','Adelaide''s own !! The latest craze taking America and Europe by storm, the phenomena of speed dating is now making its way to Adelaide. Meet 10-15 similarly aged singles in just one evening. All age groups.','/images/adelaidespeeddate_122x78.gif','http://www.adelaidespeeddate.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (770,'Forever Dance','With four studios centrally located in Richmond, Forever Dance offers everything you need in the one spot. We teach all styles of social dancing, latin/street latin and ballroom, we also host the popular “Forever Salsa” classes and “Forever fun” social club. All studios located on Church Street, Richmond','/images/foreverdance_120x80.jpg','',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (771,'Dancing Shoes Australia','PRODANCE Dance Shoes are made in Australia and are exclusive to Dancing Shoes Australia. PRODANCE are recommended by Australia''s leading Latin and Ceroc Dance studios.','/images/prodance_170x90.gif','http://www.dancingshoes.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (772,'Solo Graduates','A lifestyle club for single graduates aged 45 years and above offering many and varied social events hosted by members. Established in 1991, Solos provides good value and engaging activities with opportunities for making new friends.','/images/SG-logo-small.gif','http://www.solograduates.net.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (773,'Two Minute Tango','Don''t spend another night alone! Date 10 people instead! With over 20 tickets available this event promises to be really special for the singles of Canberra. Tickets are $50.00 (20% discount for bookings of 3 or more), including GST, gourmet nibbles through out the evening and a complimentary drink on arrival.','/images/speeddating_150x55.jpg','http://www.twominutetango.com',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (774,'Novus Social Group','A Registered Non Profit Organisation for 50+ young at hearts. Broaden your social horizon in the Eastern Suburbs. Events are organised by the members and include, parties, dinners, luncheons, walks, monthly Welcome Nights for prospective members.','/images/NovusSocialGroup_120x80.jpg','',NULL,NULL,NULL);
