INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (777,'YOUNGS Promotions','Bringing People Together Since 1989 Great venues, great music, great people. The original and the best social club for people that just want to have fun. Parties and formal functions for people 27 plus.','/images/youngs_96x80.gif','http://www.youngs-promotions.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (778,'Sacred Self based Sydney, Australia wide, International','Energetic healing, Flower & Gem essences - Sacred Self’s intention is to transform fear into love & offer healing services. We create vibrational medicine products which draw on the universal life force, Divine Mother Goddess energy, the crystal kingdom and pure essential oils. When we connect to our sacred self in our heart space, we can hear a gentle voice. Age of Miracles based Hornsby With divine guidance and inspiration, I utilize my gifts and healing abilities to assist individuals for the joy of higher vibrational states of being. Let’s begin with a cleanup… limiting belief systems, trauma, emotional and mental stress can all create blocks to our personal and spiritual growth',NULL,'http://www.sacredself.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (779,'Venus & Mars Speed Dating','Venus & Mars Speed Dating regularly hold Speed Dating in Melbourne in sophisticated and stylish settings. Check out the events page to see which event is best for you. Seats are limited for each event so reserve your seat by booking now . Are you looking for a Soul Mate? Speed Dating is the best way!','/images/vmsp_ani_120x80.gif','',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (780,'Blusuga Speed Dating in Melbourne','Bring out your sexy, stylish & devastatingly cheeky side at Blusuga! W hat if you could spend the night with numerous single eligible men/women in one of Melbourne ''s most stylish venues, dating, laughing, drinking and eating, whilst enjoying a friendly & relaxed environment?','/images/blusuga_110x85.gif','http://www.blusuga.com',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (781,'Supper Connections','A sophisticated social environment for professional and business singles in their 40''s to 60''s to meet and interact on a personal basis, make new friends, network and escape from the pressure of business. FREE MEMBERSHIP - Monthly dinner parties with 60 – 80 fun people, Sunday lunches, theatre and other activities.','/images/suppeconnections_150x104.gif','http://www.supperconnections.com',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (782,'Single Parent Family Association','The Single Parent Family Association is an exciting non-profit organisation, run by volunteers, that provides social activities and functions for single parents and their children within the Sydney area. Launched in April 1996 and with lots of interesting events each week it is the ideal organisation to join to have some fun including your children.$5 joining fee.','/images/swc_165x77.gif','http://www.singleparents.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (783,'Christian Singles and Dating','Christian Singles and Dating is an information service that matches men and women who share the same personal interests for dates, social events, or maybe just a telephone conversation. Seeking love, friendship or relationship, we can help. Dating for single women and men with Christian values.','/images/christiansingles_120x80.jpg','http://www.christiansingles.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (784,'Fun Night Out','Speed Dating is our most popular event. Speed dating is a fun and fast way to cut to the chase. We pick a groovy bar. You show up after work and relax, we will introduce you to 10 singles over drinks. Its as easy as that! 80% of our speed daters score at least one match.','/images/speed_dating_logo2.gif','http://www.funnightout.com.au',NULL,NULL,NULL);
