INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (787,'Dining Activity Network','The best and youngest Melbourne Social Club, open to all, in which members themselves organise a wide variety of events Calendar includes Dinners, Lunches, Cinema, Jazz nights, Walks, Trivia nights, Tennis, Golf, Dancing Introduction/Social Drinks Night every Friday (except January) Upstairs at The British Crown, 14 Smith Street, Collingwood. 7.45pm for 8pm start. No need to book.','/images/daanlogo_100x100.jpg','http://www.danwk.com',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (788,'Zing Factor','Tired of looking but not meeting? Zing Factor can help. Based on your partner preferences, we invite small groups of compatible singles to come to our activities. You can be sure you''ll meet everyone at our events, like pool, dinners, lawn bowls. pub trivia nights. Low-pressure, well organised, free to join and no membership fees.','/images/zing_165x69.jpg','http://www.zingfactor.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (789,'Lets Get Together','Letsget ogether is purely a FRIENDSHIP and social net-working website to provide a platform for people to meet and make new friends. It''s unique area for both Solo Parents or Seniors looking for people in a similar situation. You can create and organise your own group or activity with people of similar interests and from varying cultural backgrounds','/images/letseattogether_ani_120x80.gif','http://www.letsgettogether.com.au',NULL,NULL,NULL);
