INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (791,'Castlereagh Dance','Castlereagh Dance offers a range of dances including Ballroom, Latin, West Coast Swing, Salsa and Rock ''n Roll. A great way to meet new people and make new friends. Our venue is a great place to catch up with old friends or meet new people with a common interest. Who knows - you might even meet that someone special!','/images/CastlereaghLogo_E4S.gif','http://www.castlereaghdance.com.au',NULL,NULL,NULL);
