INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (793,'Coasters Connect Gold Coast','Coasters Connect offer a rich variety of both social and adventurous activities in a safe environment to encourage friendship and a fun way of life. Parties, Dinners, Trips Away, and endless socialising for members and a chance to expand your circle of friends. Check our monthly calendar','/images/costersConect_90x82.jpg','http://www.coastersconnect.com',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (794,'Lets Go Dance','The best social decision you will make all year. Learning to dance is fun and a rewarding experience. Dancing is our passion, teaching is our skill. Come and see our outstanding results with your first free lesson.','/images/letsgodance_120x80.gif','http://www.letsgodance.com.au',NULL,NULL,NULL);
