INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (797,'Purely Social','Join us and be prepared to create a most amazing social life. We host events - wine, cheese & chocolate appreciation, gourmet cooking classes, business networking, sporting, adventure activities and art gallery cocktail parties. Membership includes our Gourmet Club , Book Club , and Social Cinema Club.','/images/purelysocial_160x94.gif','http://www.purelysocial.com',NULL,NULL,NULL);
