INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (799,'Entre Nous','Cathy is a fully accredited Family Therapist, Relationship Counsellor and Coach, Stress Management Counsellor and Marriage Counsellor. She is an excellent communicator and her motivational skills encourage & empower. Her workshops are full of laughter and fun. Participants report that they enjoy practicing their new skills in the hands-on style workshops.','/images/entrenous_120x80.gif','http://www.singles.net.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (800,'Mystery Tours & Wild Adventure Tours','Personally guided by one of Sydney''s most experienced operators with over 10 years experience in 4WD adventure, enjoy touring Sydney and Surrounds with our comfortable air-conditioned Minibus, 2WD and 4WD OKA off-road adventure vehicles. For more information click here','/images/wildadventuretours_120x80.jpg','http://www.wildadventuretours.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (801,'Dove International','A stylish and unique lifestyle club that has been created for singles and couples of all age groups, who are keen to live life to the fullest. Our club will be providing a fantastic calendar of Leisure and Health activities and we also encourage members to look for new and exciting challenges in an environment of positive support and friendship.','/images/doveint_87x90.jpg','http://www.doveinternational.com.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (802,'Dinner for Two','Dinner for Two offers multi-tiered membership to suit individual preferences. For those who have specific requirements we offer bespoke programs. All our members have been interviewed and vetted, including the extra security of a police check. We are passionate about what we do and have worked for over 22 years bringing people together. Whether your measure of a successful match is friendship, love or romance we will help you achieve it.',NULL,'http://www.dinner-fortwo.com',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (803,'The Group','PROFESSIONAL? OVER 40? SINGLE? Want to meet and interact with like-minded people? TheGROUP.net.au is Perth''s ultimate "members only" social activities club where socialising is what it should be - easy and enjoyable. No more standing around with a drink in your hand wondering who to talk to and what to say next! Call now - we would be delighted to talk with you!','/images/thegroup_120x80.gif','http://www.thegroup.net.au',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (804,'Food Wine Conversation','A sophisticated way for like minded singles to enjoy: good food, good wine, interesting conversation and make new friends. The Club will be open on application, to persons over thirty years of age.','/images/sirromet_120x50.gif','http://www.venzin.com.au/events/',NULL,NULL,NULL);
INSERT OR IGNORE INTO businesses (id,name,description,logo_url,website,advertiser_id,created_at,updated_at) VALUES (805,'My Friends','My Friends social group offers dinners movies lunches and many special events that are fun, fabulous and truly enjoyable. Meet lots of new friends in a comfortable and relaxing atmosphere We have dinners on Fridays and Saturdays, movies nights, so just turn up and have fun.','/images/MyFriend165x27.gif','http://www.myfriends.com.au',NULL,NULL,NULL);
